//! ZK v5 track: every server-side rejection, on real proofs.
//!
//! Fixtures (`tests/fixtures/zkv5/`, regenerated by `tests/zkv5_fixtures.rs`)
//! are real `%5` proofs from the pinned miner kernel for the challenges of
//! kernel nonces 4242 (A) and 4243 (B), at the tier 2^12:
//!
//! | file                  | what it is                                         |
//! |-----------------------|----------------------------------------------------|
//! | win-{0,1,2}.jam       | three winners of A, ascending nonces               |
//! | v3-win-0.jam          | a `%3` proof of winner 0 of A                      |
//! | other-challenge.jam   | a winner of B                                      |
//! | len32.jam             | a `%5` proof of A at len 32 whose digest wins      |
//! | loser.jam             | a valid `%5` proof of A whose digest misses T_b    |
//!
//! The first half calls the checks directly ([`check_win`],
//! [`verify_win_native`]); the second goes through HTTP against a booted
//! registry, for what only the handler does (dedupe, order, count, the
//! consensus Hoon verifier, the board).

use std::sync::OnceLock;

use axum::body::Body;
use axum::http::{Request, StatusCode};
use base64::Engine;
use nockapp::noun::slab::NounSlab;
use nockapp::NounAllocator;
use nockmark_registry::zkv5::{check_win, verify_win_native};
use noun_serde::{NounDecode, NounEncode};
use tock::zkv5::{self, Belts5};
use tower::ServiceExt;
use zkvm_jetpack::form::belt::Belt;
use zkvm_jetpack::form::proof::{Proof, ProofData};

const NONCE_A: u64 = 4242;
const NONCE_B: u64 = 4243;
const TIER: u64 = 1 << 12;

const WIN0: &[u8] = include_bytes!("fixtures/zkv5/win-0.jam");
const WIN1: &[u8] = include_bytes!("fixtures/zkv5/win-1.jam");
const WIN2: &[u8] = include_bytes!("fixtures/zkv5/win-2.jam");
const V3_WIN0: &[u8] = include_bytes!("fixtures/zkv5/v3-win-0.jam");
const OTHER: &[u8] = include_bytes!("fixtures/zkv5/other-challenge.jam");
const LEN32: &[u8] = include_bytes!("fixtures/zkv5/len32.jam");
const LOSER: &[u8] = include_bytes!("fixtures/zkv5/loser.jam");

fn ca() -> Belts5 {
    zkv5::commitment_for_nonce(NONCE_A)
}

fn tb() -> Belts5 {
    zkv5::target_for_attempts(TIER).unwrap()
}

fn decode(jam: &[u8]) -> Proof {
    let mut slab: NounSlab = NounSlab::new();
    let noun = slab.cue_into(jam.to_vec().into()).unwrap();
    let space = slab.noun_space();
    Proof::from_noun(&noun, &space).unwrap()
}

fn encode(p: &Proof) -> Vec<u8> {
    let mut slab: NounSlab = NounSlab::new();
    let n = p.to_noun(&mut slab);
    slab.set_root(n);
    slab.jam().to_vec()
}

/// `jam` with one belt of the first Merkle root AFTER object 0 changed: the
/// same object 0 (same nonce, same digest), a different — here invalid —
/// witness suffix.
fn mutate_suffix(jam: &[u8]) -> Vec<u8> {
    let mut p = decode(jam);
    let root = p
        .objects
        .iter_mut()
        .skip(1)
        .find_map(|o| match o {
            ProofData::MRoot { p } => Some(p),
            _ => None,
        })
        .expect("a proof has a Merkle root after object 0");
    root[0] = if root[0] == 0 { 1 } else { root[0] - 1 };
    encode(&p)
}

/// `jam` with a high zero coefficient appended to its first `%poly`: the same
/// polynomial, written non-canonically (what `+canonical-pow-proof` refuses).
fn non_canonical_poly(jam: &[u8]) -> Vec<u8> {
    let mut p = decode(jam);
    let poly = p
        .objects
        .iter_mut()
        .find_map(|o| match o {
            ProofData::Poly(p) => Some(p),
            _ => None,
        })
        .expect("a proof has a %poly object");
    poly.0.push(Belt(0));
    encode(&p)
}

/// `jam` with one belt of object 0's puzzle product changed: the same
/// commitment, nonce and len, but not the puzzle object they define.
fn tamper_product(jam: &[u8]) -> Vec<u8> {
    let mut p = decode(jam);
    match &mut p.objects[0] {
        ProofData::Puzzle { leaf, .. } => leaf[0] = if leaf[0] == 0 { 1 } else { leaf[0] - 1 },
        o => panic!("object 0 is {o:?}"),
    }
    encode(&p)
}

fn nonce_of(jam: &[u8]) -> Belts5 {
    match &decode(jam).objects[0] {
        ProofData::Puzzle { nonce, .. } => *nonce,
        o => panic!("object 0 is {o:?}"),
    }
}

// ---------------------------------------------------------------------------
// The checks, called directly
// ---------------------------------------------------------------------------

#[test]
fn real_wins_pass_every_check() {
    let mut nonces = Vec::new();
    for jam in [WIN0, WIN1, WIN2] {
        let w = check_win(&ca(), &tb(), jam).expect("a real winner passes the cheap checks");
        nonces.push(w.nonce);
        assert_eq!(
            w.digest,
            zk_pow_miner::v5::v5_pow_digest(ca(), w.nonce, 64),
            "the digest re-derived from the submitted object 0 is upstream's"
        );
        verify_win_native(w, &ca(), 7).expect("and its STARK verifies natively");
    }
    assert!(zkv5::nonces_strictly_ascending(&nonces));
}

#[test]
fn rejects_a_v3_proof() {
    let e = check_win(&ca(), &tb(), V3_WIN0).err().expect("rejected");
    assert!(e.contains("version"), "{e}");
}

#[test]
fn rejects_a_proof_for_another_challenge() {
    let e = check_win(&ca(), &tb(), OTHER).err().expect("rejected");
    assert!(e.contains("commitment"), "{e}");
    // It is a perfectly good win of the challenge it was made for.
    let cb = zkv5::commitment_for_nonce(NONCE_B);
    let w = check_win(&cb, &tb(), OTHER).expect("valid for B");
    verify_win_native(w, &cb, 7).unwrap();
}

#[test]
fn rejects_len_other_than_64() {
    let e = check_win(&ca(), &tb(), LEN32).err().expect("rejected");
    assert!(e.contains("len 32"), "{e}");
}

#[test]
fn rejects_a_digest_above_the_target() {
    let e = check_win(&ca(), &tb(), LOSER).err().expect("rejected");
    assert!(e.contains("does not meet the challenge target"), "{e}");
    // The proof itself is valid: only the lottery check stops it.
    let max = zkv5::to_base_p(&zkv5::max_tip5_atom()).unwrap();
    let w = check_win(&ca(), &max, LOSER).expect("passes at the maximum target");
    verify_win_native(w, &ca(), 7).unwrap();
}

#[test]
fn rejects_a_tampered_puzzle_object() {
    let e = check_win(&ca(), &tb(), &tamper_product(WIN0))
        .err()
        .expect("rejected");
    assert!(e.contains("canonical puzzle object"), "{e}");
}

#[test]
fn rejects_a_non_canonical_polynomial() {
    let e = check_win(&ca(), &tb(), &non_canonical_poly(WIN0))
        .err()
        .expect("rejected");
    assert!(e.contains("non-canonical polynomial"), "{e}");
}

#[test]
fn a_mutated_suffix_keeps_object_0_and_fails_the_stark() {
    let bad = mutate_suffix(WIN0);
    assert_ne!(bad, WIN0);
    // Object 0 is untouched, so the cheap checks pass and the nonce is the same:
    // the dedupe has to be on the nonce, not on the proof bytes.
    let w = check_win(&ca(), &tb(), &bad).expect("object 0 unchanged");
    assert_eq!(w.nonce, nonce_of(WIN0));
    let e = verify_win_native(w, &ca(), 7).err().expect("STARK fails");
    assert!(e.contains("STARK verification failed"), "{e}");
}

#[test]
fn rejects_garbage_and_oversize() {
    assert!(check_win(&ca(), &tb(), b"not a jam").is_err());
    let e = check_win(
        &ca(),
        &tb(),
        &vec![0u8; nockmark_registry::zkv5::ZK_PROOF_JAM_MAX + 1],
    )
    .err()
    .unwrap();
    assert!(e.contains("exceeds"), "{e}");
}

// ---------------------------------------------------------------------------
// Through HTTP
// ---------------------------------------------------------------------------

/// One booted kernel + roswell per test at a time (they allocate huge stacks).
fn test_lock() -> &'static tokio::sync::Mutex<()> {
    static LOCK: OnceLock<tokio::sync::Mutex<()>> = OnceLock::new();
    LOCK.get_or_init(|| tokio::sync::Mutex::new(()))
}

/// A registry with k = 2 and challenges A and B pending at the fixture tier,
/// issued now (seeded into the store, as if minted).
async fn state() -> nockmark_registry::http::AppState {
    let dir = tempfile::tempdir().unwrap();
    {
        let mut s = nockmark_registry::zkv5::ZkV5Store::load(
            nockmark_registry::zkv5::ZkV5Store::path_in(dir.path()),
        )
        .unwrap();
        let now = nockmark_registry::aipow::unix_ms();
        s.record_challenge(NONCE_A, now, tb(), TIER).unwrap();
        s.record_challenge(NONCE_B, now, tb(), TIER).unwrap();
    }
    let jam = std::path::Path::new(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../tock/assets/registry.jam"
    ));
    let st = nockmark_registry::http::AppState::boot_with_k(jam, dir.path(), 2)
        .await
        .unwrap();
    std::mem::forget(dir); // the kernel's checkpoints live there
    st
}

/// Each POST from its own client address: the POST routes are rate-limited
/// per IP (10/min), and these tests make more requests than that.
async fn post(
    app: axum::Router,
    path: &str,
    body: serde_json::Value,
) -> (StatusCode, serde_json::Value) {
    static CLIENT: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0);
    let n = CLIENT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let res = app
        .oneshot(
            Request::post(path)
                .header("content-type", "application/json")
                .header("x-forwarded-for", format!("198.51.100.{}", n % 250))
                .body(Body::from(body.to_string()))
                .unwrap(),
        )
        .await
        .unwrap();
    let status = res.status();
    let bytes = axum::body::to_bytes(res.into_body(), 64 << 20)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(serde_json::json!({})),
    )
}

async fn get(app: axum::Router, path: &str) -> (StatusCode, serde_json::Value) {
    let res = app
        .oneshot(Request::get(path).body(Body::empty()).unwrap())
        .await
        .unwrap();
    let status = res.status();
    let bytes = axum::body::to_bytes(res.into_body(), 64 << 20)
        .await
        .unwrap();
    (
        status,
        serde_json::from_slice(&bytes).unwrap_or(serde_json::json!({})),
    )
}

fn submission(nonce: u64, proofs: &[&[u8]]) -> serde_json::Value {
    serde_json::json!({
        "nonce": nonce.to_string(),
        "hardware": "zkv5-test",
        "prover_version": "ed1edfcc",
        "grind_elapsed_ms": 50,
        "proofs": proofs.iter().map(|p| base64::engine::general_purpose::STANDARD.encode(p)).collect::<Vec<_>>(),
    })
}

/// Submit and expect a 400 whose error contains `needle`.
async fn rejected(app: &axum::Router, nonce: u64, proofs: &[&[u8]], needle: &str) {
    let (status, body) = post(app.clone(), "/run?track=zk", submission(nonce, proofs)).await;
    let err = body["error"].as_str().unwrap_or("").to_string();
    assert_eq!(status, StatusCode::BAD_REQUEST, "{needle}: {body}");
    assert!(err.contains(needle), "expected {needle:?}, got {err:?}");
}

#[tokio::test]
async fn challenge_is_derived_from_the_nonce_and_v3_is_retired() {
    let _g = test_lock().lock().await;
    let app = nockmark_registry::http::router(state().await);
    let (status, ch) = post(
        app.clone(),
        "/challenge?track=zk&attempts=5000",
        serde_json::json!({}),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{ch}");
    let nonce: u64 = ch["nonce"].as_str().unwrap().parse().unwrap();
    let strings = |v: &serde_json::Value| -> Vec<String> {
        v.as_array()
            .unwrap()
            .iter()
            .map(|s| s.as_str().unwrap().to_string())
            .collect()
    };
    assert_eq!(
        ch["attempts"], 4096,
        "5000 rounds to the nearest power of two"
    );
    assert_eq!(
        zkv5::belts_from_strings(&strings(&ch["commitment"])).unwrap(),
        zkv5::commitment_for_nonce(nonce)
    );
    assert_eq!(
        zkv5::belts_from_strings(&strings(&ch["target"])).unwrap(),
        zkv5::target_for_attempts(4096).unwrap()
    );
    assert_eq!(
        ch["challenge"],
        tock::aipow::hex32(&zkv5::challenge32(nonce))
    );
    assert_eq!(
        (
            ch["k"].as_u64(),
            ch["pow_len"].as_u64(),
            ch["proof_version"].as_u64()
        ),
        (Some(2), Some(64), Some(5))
    );
    assert_eq!(ch["nonce_rule"], zkv5::ZK_V5_NONCE_RULE);
    // A malformed tier mints nothing.
    let (status, _) = post(
        app.clone(),
        "/challenge?track=zk&attempts=lots",
        serde_json::json!({}),
    )
    .await;
    assert_eq!(status, StatusCode::BAD_REQUEST);
    // Untracked writes are the retired %3 path.
    let (status, body) = post(app.clone(), "/challenge", serde_json::json!({})).await;
    assert_eq!(status, StatusCode::GONE);
    assert!(
        body["error"].as_str().unwrap().contains("track=zk"),
        "{body}"
    );
    let (status, _) = post(app.clone(), "/run", serde_json::json!({})).await;
    assert_eq!(status, StatusCode::GONE);
    let (status, _) = post(app, "/challenge?track=zk3", serde_json::json!({})).await;
    assert_eq!(status, StatusCode::BAD_REQUEST, "unknown track");
}

/// Every handler-level rejection, then the honest submission on the SAME
/// challenge: rejections must not burn it.
#[tokio::test]
async fn run_rejections_then_acceptance_and_the_board() {
    let _g = test_lock().lock().await;
    let st = state().await;
    let app = nockmark_registry::http::router(st.clone());

    // A pre-Anthropos row in the kernel, which must stay listed but unranked.
    let old = st.kernel.lock().await.mint_challenge().await.unwrap();
    tokio::time::sleep(std::time::Duration::from_millis(300)).await;
    st.kernel
        .lock()
        .await
        .submit_run(old, "old-cpu", "c8d6b13e", 2, 100)
        .await
        .unwrap()
        .unwrap();

    rejected(&app, NONCE_A, &[V3_WIN0, WIN1], "version").await;
    rejected(&app, NONCE_A, &[OTHER, WIN1], "commitment").await;
    rejected(&app, NONCE_A, &[LEN32, WIN1], "len 32").await;
    rejected(
        &app,
        NONCE_A,
        &[LOSER, WIN1],
        "does not meet the challenge target",
    )
    .await;
    rejected(&app, NONCE_A, &[WIN0, WIN0], "duplicate win").await;
    rejected(
        &app,
        NONCE_A,
        &[WIN0, &mutate_suffix(WIN0)],
        "duplicate win",
    )
    .await;
    rejected(&app, NONCE_A, &[WIN1, WIN0], "strictly ascending").await;
    rejected(
        &app,
        NONCE_A,
        &[WIN0, &mutate_suffix(WIN1)],
        "STARK verification failed",
    )
    .await;
    rejected(
        &app,
        NONCE_A,
        &[WIN0, &non_canonical_poly(WIN1)],
        "non-canonical",
    )
    .await;
    rejected(
        &app,
        NONCE_A,
        &[WIN0, &tamper_product(WIN1)],
        "canonical puzzle object",
    )
    .await;
    rejected(&app, NONCE_A, &[WIN0, WIN1, WIN2], "expected 2 proofs").await;
    rejected(&app, 99, &[WIN0, WIN1], "unknown-nonce").await;
    // A replayed proof from another challenge, on its own.
    rejected(&app, NONCE_B, &[WIN0, WIN1], "commitment").await;

    let (status, body) = post(
        app.clone(),
        "/run?track=zk",
        submission(NONCE_A, &[WIN0, WIN1]),
    )
    .await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(body["run_id"], 1);
    // The same proofs again: the challenge is spent.
    rejected(&app, NONCE_A, &[WIN0, WIN1], "nonce-used").await;

    let (status, board) = get(app.clone(), "/leaderboard?track=zk").await;
    assert_eq!(status, StatusCode::OK);
    let rows = board.as_array().unwrap();
    assert_eq!(rows.len(), 2, "{board}");
    let v5 = &rows[0];
    assert_eq!(
        (v5["rank"].as_u64(), v5["rules"].as_str()),
        (Some(1), Some("anthropos"))
    );
    assert_eq!(v5["k"], 2);
    assert_eq!(v5["attempts"], TIER);
    assert_eq!(v5["expected_attempts_per_win"].as_f64(), Some(TIER as f64));
    let window = v5["server_window_ms"].as_u64().unwrap();
    let want = 2.0 * TIER as f64 / (window as f64 / 1000.0);
    let got = v5["verified_zk_hashes_per_sec_lb"].as_f64().unwrap();
    assert!((got - want).abs() <= want * 1e-3, "{got} vs {want}");
    assert_eq!(v5["win_nonces"].as_array().unwrap().len(), 2);
    let old = &rows[1];
    assert_eq!(
        (old["rules"].as_str(), old["rank"].is_null()),
        (Some("pre-anthropos"), true)
    );
    assert_eq!(old["hardware"], "old-cpu");
    // The untracked board is the same board.
    assert_eq!(get(app.clone(), "/leaderboard").await.1, board);
    // /runs/:id per track: v5 with its rank, untracked = the kernel's run.
    let (status, run) = get(app.clone(), "/runs/1?track=zk").await;
    assert_eq!((status, run["rank"].as_u64()), (StatusCode::OK, Some(1)));
    let old_id = old["id"].as_u64().unwrap(); // the kernel numbers from 0
    let (status, run) = get(app, &format!("/runs/{old_id}")).await;
    assert_eq!(
        (status, run["hardware"].as_str()),
        (StatusCode::OK, Some("old-cpu"))
    );
}
